parts=re.split(r'(<[^>]+>)',doc);skip=False
for i,t in enumerate(parts):
 if t.startswith('<'):
  if re.match(r'<(?:style|a|code)\b',t):skip=True
  elif re.match(r'</(?:style|a|code)>',t):skip=False
 elif not skip:
  t=html.unescape(t)
  t=t.replace('Float64Array','ARRAYFLOATSIXTYFOUR').replace('Float64','FLOATSIXTYFOUR').replace('float32','FLOATTHIRTYTWO').replace('float64','FLOATSIXTYFOUR').replace('Top10','Top-10')
  t=re.sub(r'(?<=[a-z])(?=\d)',' ',t)
  t=re.sub(r'(?<=[a-z])(?=\.\d)',' ',t)
  t=re.sub(r'\b(ID|IDs|MF|RMSE|HTTP|IEEE)(?=\d|\.\d)',r'\1 ',t)
  t=re.sub(r'(?<=[A-Za-z]),(?=\d)',', ',t)
  t=t.replace('versus+','versus +').replace('ratings≥','ratings ≥ ').replace('degree≤','degree ≤ ').replace('degree>','degree > ')
  t=t.replace('ARRAYFLOATSIXTYFOUR','Float64Array').replace('FLOATTHIRTYTWO','float32').replace('FLOATSIXTYFOUR','float64')
  parts[i]=html.escape(t,quote=False)
doc=''.join(parts)
doc=doc.replace('href="../week6/report/', 'href="https://github.com/gillsha/ML_homework/blob/main/week6/report/').replace('href="../week6/results/', 'href="https://github.com/gillsha/ML_homework/blob/main/week6/results/')
