def flatten(v,path,src):
 if isinstance(v,dict):
  for k,x in v.items():flatten(x,path+'/'+k,src)
 elif isinstance(v,list):
  for i,x in enumerate(v):flatten(x,path+'/'+str(i),src)
 else:
  if isinstance(v,(int,float,bool)) or any(t in path for t in ['version','browser','seed','label','title','checkpoint','status']):trace('Evidence field',v,'week6/results/'+src,path)
for src,keys in sources.items():
 data=load(src)
 if keys:
  for key in keys:
   if key in data:flatten(data[key],'/'+key,src)
 else:flatten(data,'',src)
